'pomerol-chateau-vray-croix-de-gay|2012':{blend:{ME:80,CF:20},yld:47,months:'9',press:{'La Revue du Vin de France':'20'},src:'FT_Plaisir_2012_EN.pdf',taste:'Very round (smooth tannins), very fruity (lively red berries aromas) The Vineyard TERROIR : gravel, deep clays, sandy clays SURFACE AREA : 46,18 ha VITICULTURE BY PLOT : 40 plots, in conversion to organic viticulture and using biodynamic cultivation techniques.'},
