'brane-cantenac|2015':{yld:51,src:'Brane-Cantenac-2015-FT-FR-5.pdf',via:'trade'},
'brane-cantenac|2017':{blend:{CS:74,ME:21,CF:4,PV:1},alc:13,ph:3.76,src:'Brane-Cantenac-2017-FT-FR.pdf',via:'trade'},
'brane-cantenac|2019':{yld:50,src:'Brane-Cantenac-FT_2019_FR.pdf',via:'trade',note:'2019 Une année d’anthologie à Brane. Tous les 30 ans : 1899-1929-1959-1989… mais pas seulement.'},
'brane-cantenac|2021':{blend:{CS:74,ME:22,CF:2,PV:1,CA:1},alc:12.7,ph:3.66,press:{'Decanter':'95','James Suckling':'94-95','Neal Martin':'92-94','Vinous':'93-96','Wine Advocate':'93-95'},src:'sites_Millesimes_2021_Brane-Cantenac_Fiches-techniques_presentation-BC-2021-FR.pdf',via:'trade'},
'brane-cantenac|2025':{blend:{CS:80,ME:18,CF:1,CA:1},ph:3.62,yld:32.2,src:'Document_primeur_Chateau_Brane_Cantenac_MAR_RO_2025.pdf',via:'trade',note:'2025 marked 100 years of the family at Château Brane-Cantenac. Brane embodies the legacy of a family passion for wine, passed down through five generations. In 1925, Léonce Récapet acquired the estate. Since 1992, Henri Lurton, his great-grandson, has managed it with passion, as both a visionary and guardian of this exceptional terroir. In 2022, he passed the ownership on to his children while retaining its management. Together, they perpetuate a savoir-faire of excellence, guided by a sustainable and nature-respecting approach. Each vintage reflects their philosophy: to craft wines that are elegant, balanced, and deeply authentic.'},
'canon|2019':{blend:{ME:74,CF:26},ph:3.5,yld:45,months:'18',oak:50,src:'Fiche_technique_Chateau_CANON_EMI_RO_2019_Anglais.pdf',via:'trade',note:'Winter: very mild Spring: cool Summer: exceptionnaly hot and dry Autumn: very fine start to the season, some rainfall end September HARVEST TIME Merlot: 11 to 26 September Cabernet Franc: 27 September to 4 October YIELD 45hl / ha AGEING 18 months with 50% new barrels for Château Canon & 30% for Croix Canon 2019 VINTAGE Barely opened, it escapes from the bottle like a sweet summer scent... Ripe and expressive, bursting with life, the wine plunges into the glass in which bright notes of red fruit, lush strawberries and raspberries, spin around each other. A few more swirls of the glass and the fruit intensifies even further, allowing aromas of morello cherry burst forth. There is this constant sensation of sapidity, so smooth and tasty.'},
'clinet|2019':{blend:{CS:20,ME:80},alc:14.5,yld:38,months:'16',oak:25,press:{'Yves Beck':'95'},src:'CHATEAU-CLINET-2019-AOC-POMEROL-FICHE-PRODUIT.pdf',via:'trade'},
