'ferriere|2021':{blend:{CS:81,ME:13,PV:5},months:'18',oak:40,src:'sites_Millesimes_2021_Ferriere_Fiches-techniques_Ferriere-2021-FT-FR-Primeurs.pdf',via:'trade',note:'2021 SE MONTRERAIT AUSSI SÉDUISANT, LONG ET ÉLÉGANT ? À L’ISSUE D’UN SPLENDIDE MOIS DE SEPTEMBRE, LE RÉSULTAT EST LÀ : UN TRÈS BON MILLÉSIME, AVEC BEAUCOUP DE CARACTÈRE.'},
