'stem-chateau-dassault|2015':{blend:{CS:5,ME:75,CF:20},yld:33.5,months:'14-18',oak:65,src:'Dassault-2015-FT-FR-547.pdf',via:'trade'},
'stem-chateau-dassault|2016':{blend:{CS:5,ME:73,CF:22},yld:33,months:'14-18',oak:70,src:'Dassault-2016-FT-FR-547.pdf',via:'trade'},
'stem-chateau-dassault|2018':{blend:{CS:3,ME:75,CF:22},months:'14-18',oak:70,src:'Dassault-2018-FT-FR.pdf',via:'trade'},
'stem-chateau-dassault|2020':{blend:{CS:3,ME:86,CF:11},months:'12-16',oak:33,src:'ChDassault2020-EN.pdf',via:'trade'},
'stem-chateau-dassault|2021':{blend:{CS:10,ME:60,CF:30},alc:13.3,ph:3.6,months:'12-16',oak:70,src:'FT-ChDassault2021-FR.pdf',via:'trade'},
'stem-chateau-dassault|2024':{blend:{CS:4,ME:71,CF:25},months:'12-16',oak:61,src:'ft_dassault-2024_dassault-2024-ft-fr-primeurs.pdf',via:'trade',taste:'Couleur rouge grenat, avec des reflets violacés. Vin limpide et brillant. Au nez, notes de fruit frais, griotte. On retrouve l’aromatique fruité en bouche avec des notes de bonbons Anglais. Mûr, avec du goût, le Château Dassault 2024 est très gourmand, plein et juteux, avec un bel équilibre.'},
'stem-chateau-faugeres|2016':{blend:{CS:5,ME:85,CF:10},src:'Chateau-Cap-de-Faugeres-nouvel-habillage-2016.pdf',via:'trade'},
